1	/**
2	 * @module useRealTimeTracking
3	 *
4	 * Hook principal de rastreamento em tempo real para motoristas.
5	 * Gerencia sessões de motorista, corridas ativas, localizações GPS
6	 * e assinaturas Supabase Realtime nas tabelas de logística.
7	 */
8	
9	import { useState, useEffect, useCallback, useRef } from 'react';
10	import { supabase } from '@/integrations/supabase/client';
11	import { toast } from '@/shared/hooks/use-toast';
12	import { useTripTimer } from '@/features/logistica/model/useTripTimer';
13	import type { RealtimeChannel } from '@supabase/supabase-js';
14	import { calcularDistanciaMetros } from '@/shared/lib/haversine';
15	import { handleError } from '@/shared/lib/error-handler';
16	import { wideDebug, wideWarn } from '@/shared/lib/telemetry/wide-events';
17	
18	/** Sessão ativa de um motorista com dados de veículo e última posição GPS. */
19	interface SessaoMotorista {
20	  id: number;
21	  user_id: string;
22	  nome: string;
23	  veiculo_placa: string;
24	  veiculo_modelo: string;
25	  ativo: boolean;
26	  latitude: number;
27	  longitude: number;
28	  ultima_atualizacao: string;
29	}
30	
31	/** Corrida (viagem) vinculada a uma sessão, com origem, destino e status. */
32	interface CorridaAtiva {
33	  id: number;
34	  sessao_motorista_id: number;
35	  destino_nome: string;
36	  destino_latitude: number;
37	  destino_longitude: number;
38	  inicio_latitude: number;
39	  inicio_longitude: number;
40	  distancia_percorrida: number;
41	  tempo_inicio: string;
42	  tempo_fim: string | null;
43	  status: 'ativa' | 'finalizada' | 'cancelada';
44	}
45	
46	/** Ponto de localização GPS registrado durante uma corrida. */
47	interface LocalizacaoCorrida {
48	  id: number;
49	  corrida_id: number;
50	  latitude: number;
51	  longitude: number;
52	  velocidade: number;
53	  timestamp_localizacao: string;
54	}
55	
56	/** Loja/ponto cadastrado com coordenadas para exibição no mapa. */
57	interface Loja {
58	  id: number;
59	  nome: string;
60	  endereco: string;
61	  latitude: number;
62	  longitude: number;
63	  tipo: string;
64	  ativo: boolean;
65	}
66	
67	interface UseRealTimeTrackingReturn {
68	  sessoesMotorista: SessaoMotorista[];
69	  corridasAtivas: CorridaAtiva[];
70	  localizacoesCorrida: LocalizacaoCorrida[];
71	  lojas: Loja[];
72	  minhaSessao: SessaoMotorista | null;
73	  minhaCorridaAtiva: CorridaAtiva | null;
74	  loading: boolean;
75	  error: string | null;
76	  isDriverMode: boolean;
77	  entrarComoMotorista: (
78	    nome: string,
79	    placa?: string,
80	    modelo?: string,
81	  ) => Promise<void>;
82	  sairModoMotorista: () => Promise<void>;
83	  iniciarCorrida: (
84	    destinoNome: string,
85	    destinoLat: number,
86	    destinoLng: number,
87	  ) => Promise<void>;
88	  finalizarCorrida: () => Promise<void>;
89	  atualizarLocalizacao: (
90	    lat: number,
91	    lng: number,
92	    velocidade?: number,
93	  ) => Promise<void>;
94	  refetch: () => Promise<void>;
95	  reloadLojas: () => Promise<void>;
96	}
97	
98	/**
99	 * Gerencia rastreamento em tempo real de motoristas e corridas.
100	 *
101	 * Carrega sessões ativas, corridas e localizações do Supabase,
102	 * configura canais Realtime e expõe métodos para entrar/sair do
103	 * modo motorista, iniciar/finalizar corridas e atualizar posição GPS.
104	 *
105	 * @returns Estado de sessões, corridas, lojas e funções de controle.
106	 */
107	export const useRealTimeTracking = (): UseRealTimeTrackingReturn => {
108	  const [sessoesMotorista, setSessoesMotorista] = useState<SessaoMotorista[]>(
109	    [],
110	  );
111	  const [corridasAtivas, setCorridasAtivas] = useState<CorridaAtiva[]>([]);
112	  const [localizacoesCorrida, setLocalizacoesCorrida] = useState<
113	    LocalizacaoCorrida[]
114	  >([]);
115	  const [lojas, setLojas] = useState<Loja[]>([]);
116	  const [minhaSessao, setMinhaSessao] = useState<SessaoMotorista | null>(null);
117	  const [minhaCorridaAtiva, setMinhaCorridaAtiva] =
118	    useState<CorridaAtiva | null>(null);
119	  const [loading, setLoading] = useState(true);
120	  const [error, setError] = useState<string | null>(null);
121	  const [isDriverMode, setIsDriverMode] = useState(false);
122	  const [channels, setChannels] = useState<RealtimeChannel[]>([]);
123	  const locationUpdateIntervalRef = useRef<NodeJS.Timeout | null>(null);
124	  const channelsRef = useRef<RealtimeChannel[]>([]);
125	
126	  // Inicializar o timer de viagem
127	  const tripTimer = useTripTimer();
128	
129	  // Atualizar ref quando channels mudar
130	  useEffect(() => {
131	    channelsRef.current = channels;
132	  }, [channels]);
133	
134	  // Carregar dados iniciais
135	  const carregarDados = useCallback(async () => {
136	    try {
137	      setLoading(true);
138	      setError(null);
139	
140	      // Carregar sessões de motorista ativas
141	      const { data: sessoesData, error: sessoesError } = await supabase
142	        .from('sessoes_motorista')
143	        .select('*')
144	        .eq('ativo', true);
145	
146	      if (sessoesError) throw sessoesError;
147	      setSessoesMotorista(sessoesData || []);
148	
149	      // Carregar corridas ativas
150	      const { data: corridasData, error: corridasError } = await supabase
151	        .from('corridas_ativas')
152	        .select('*')
153	        .eq('status', 'ativa');
154	
155	      if (corridasError) throw corridasError;
156	      setCorridasAtivas(corridasData || []);
157	
158	      // Carregar localizações das corridas ativas
159	      if (corridasData && corridasData.length > 0) {
160	        const corridaIds = corridasData.map((c) => c.id);
161	        const { data: localizacoesData, error: localizacoesError } =
162	          await supabase
163	            .from('localizacoes_corrida')
164	            .select('*')
165	            .in('corrida_id', corridaIds)
166	            .order('timestamp_localizacao', { ascending: false });
167	
168	        if (localizacoesError) throw localizacoesError;
169	        setLocalizacoesCorrida(localizacoesData || []);
170	      }
171	
172	      // Carregar lojas
173	      const { data: lojasData, error: lojasError } = await supabase
174	        .from('lojas')
175	        .select('*')
176	        .eq('ativo', true);
177	
178	      if (lojasError) throw lojasError;
179	      setLojas(lojasData || []);
180	
181	      // Verificar se o usuário atual tem uma sessão ativa
182	      const {
183	        data: { user },
184	      } = await supabase.auth.getUser();
185	      if (user && sessoesData) {
186	        const minhaSessaoAtual = sessoesData.find((s) => s.user_id === user.id);
187	        if (minhaSessaoAtual) {
188	          setMinhaSessao(minhaSessaoAtual);
189	          setIsDriverMode(true);
190	
191	          // Verificar se tem corrida ativa
192	          const minhaCorridaAtual = corridasData?.find(
193	            (c) => c.sessao_motorista_id === minhaSessaoAtual.id,
194	          );
195	          if (minhaCorridaAtual) {
196	            setMinhaCorridaAtiva(minhaCorridaAtual);
197	          }
198	        }
199	      }
200	    } catch (error) {
201	      handleError(error, { domain: 'logistica', operation: 'carregarDados', showToast: false });
202	      setError(error instanceof Error ? error.message : 'Erro desconhecido');
203	    } finally {
204	      setLoading(false);
205	    }
206	  }, []);
207	
208	  // Função estável para recarregar dados
209	  const recarregarDados = useCallback(async () => {
210	    try {
211	      // Carregar sessões de motorista ativas
212	      const { data: sessoesData, error: sessoesError } = await supabase
213	        .from('sessoes_motorista')
214	        .select('*')
215	        .eq('ativo', true);
216	
217	      if (sessoesError) throw sessoesError;
218	      setSessoesMotorista(sessoesData || []);
219	
220	      // Carregar corridas ativas
221	      const { data: corridasData, error: corridasError } = await supabase
222	        .from('corridas_ativas')
223	        .select('*')
224	        .eq('status', 'ativa');
225	
226	      if (corridasError) throw corridasError;
227	      setCorridasAtivas(corridasData || []);
228	
229	      // Carregar localizações das corridas ativas
230	      if (corridasData && corridasData.length > 0) {
231	        const corridaIds = corridasData.map((c) => c.id);
232	        const { data: localizacoesData, error: localizacoesError } =
233	          await supabase
234	            .from('localizacoes_corrida')
235	            .select('*')
236	            .in('corrida_id', corridaIds)
237	            .order('timestamp_localizacao', { ascending: false });
238	
239	        if (localizacoesError) throw localizacoesError;
240	        setLocalizacoesCorrida(localizacoesData || []);
241	      }
242	
243	      // Verificar se o usuário atual tem uma sessão ativa
244	      const {
245	        data: { user },
246	      } = await supabase.auth.getUser();
247	      if (user && sessoesData) {
248	        const minhaSessaoAtual = sessoesData.find((s) => s.user_id === user.id);
249	        if (minhaSessaoAtual) {
250	          setMinhaSessao(minhaSessaoAtual);
251	          setIsDriverMode(true);
252	
253	          // Verificar se tem corrida ativa
254	          const minhaCorridaAtual = corridasData?.find(
255	            (c) => c.sessao_motorista_id === minhaSessaoAtual.id,
256	          );
257	          if (minhaCorridaAtual) {
258	            setMinhaCorridaAtiva(minhaCorridaAtual);
259	          }
260	        }
261	      }
262	    } catch (error) {
263	      handleError(error, { domain: 'logistica', operation: 'recarregarDados', showToast: false });
264	    }
265	  }, []);
266	
267	  // Configurar subscriptions do Supabase Realtime
268	  const configurarRealtime = useCallback(() => {
269	    // Limpar canais existentes
270	    channelsRef.current.forEach((channel) => {
271	      supabase.removeChannel(channel);
272	    });
273	
274	    const newChannels: RealtimeChannel[] = [];
275	
276	    // Canal para sessões de motorista
277	    const sessaoChannel = supabase
278	      .channel('sessoes_motorista_changes')
279	      .on(
280	        'postgres_changes',
281	        {
282	          event: '*',
283	          schema: 'public',
284	          table: 'sessoes_motorista',
285	        },
286	        (payload) => {
287	          wideDebug('logistica.realtime.sessaoChange', 'Mudança detectada em sessões de motorista', { domain: 'logistica', attributes: { eventType: payload.eventType } });
288	          recarregarDados();
289	        },
290	      )
291	      .subscribe();
292	
293	    newChannels.push(sessaoChannel);
294	
295	    // Canal para corridas ativas
296	    const corridaChannel = supabase
297	      .channel('corridas_ativas_changes')
298	      .on(
299	        'postgres_changes',
300	        {
301	          event: '*',
302	          schema: 'public',
303	          table: 'corridas_ativas',
304	        },
305	        (payload) => {
306	          wideDebug('logistica.realtime.corridaChange', 'Mudança detectada em corridas ativas', { domain: 'logistica', attributes: { eventType: payload.eventType } });
307	          recarregarDados();
308	        },
309	      )
310	      .subscribe();
311	
312	    newChannels.push(corridaChannel);
313	
314	    // Canal para localizações de corrida
315	    const localizacaoChannel = supabase
316	      .channel('localizacoes_corrida_changes')
317	      .on(
318	        'postgres_changes',
319	        {
320	          event: '*',
321	          schema: 'public',
322	          table: 'localizacoes_corrida',
323	        },
324	        (payload) => {
325	          wideDebug('logistica.realtime.localizacaoChange', 'Mudança detectada em localizações de corrida', { domain: 'logistica', attributes: { eventType: payload.eventType } });
326	          recarregarDados();
327	        },
328	      )
329	      .subscribe();
330	
331	    newChannels.push(localizacaoChannel);
332	
333	    setChannels(newChannels);
334	    channelsRef.current = newChannels;
335	  }, [recarregarDados]);
336	
337	  // Entrar como motorista
338	  const entrarComoMotorista = useCallback(
339	    async (nome: string, placa?: string, modelo?: string) => {
340	      try {
341	        const {
342	          data: { user },
343	        } = await supabase.auth.getUser();
344	        if (!user) {
345	          throw new Error('Usuário não autenticado');
346	        }
347	
348	        // Verificar se já existe uma sessão ativa
349	        const { data: sessaoExistente } = await supabase
350	          .from('sessoes_motorista')
351	          .select('*')
352	          .eq('user_id', user.id)
353	          .eq('ativo', true)
354	          .single();
355	
356	        if (sessaoExistente) {
357	          setMinhaSessao(sessaoExistente);
358	          setIsDriverMode(true);
359	          toast({
360	            title: 'Sessão Ativa',
361	            description: 'Você já possui uma sessão ativa como motorista.',
362	          });
363	          return;
364	        }
365	
366	        // Criar nova sessão
367	        const { data: novaSessao, error } = await supabase
368	          .from('sessoes_motorista')
369	          .insert({
370	            user_id: user.id,
371	            nome,
372	            veiculo_placa: placa || '',
373	            veiculo_modelo: modelo || '',
374	          })
375	          .select()
376	          .single();
377	
378	        if (error) throw error;
379	
380	        setMinhaSessao(novaSessao);
381	        setIsDriverMode(true);
382	
383	        toast({
384	          title: 'Modo Motorista Ativado',
385	          description: `Bem-vindo, ${nome}! Você está agora no modo motorista.`,
386	        });
387	      } catch (error) {
388	        handleError(error, { domain: 'logistica', operation: 'entrarComoMotorista', showToast: false });
389	        setError(
390	          error instanceof Error
391	            ? error.message
392	            : 'Erro ao entrar como motorista',
393	        );
394	      }
395	    },
396	    [],
397	  );
398	
399	  // Sair do modo motorista
400	  const sairModoMotorista = useCallback(async () => {
401	    try {
402	      if (!minhaSessao) return;
403	
404	      // Finalizar corrida ativa se existir
405	      if (minhaCorridaAtiva) {
406	        await finalizarCorrida();
407	      }
408	
409	      // Desativar sessão
410	      const { error } = await supabase
411	        .from('sessoes_motorista')
412	        .update({ ativo: false })
413	        .eq('id', minhaSessao.id);
414	
415	      if (error) throw error;
416	
417	      setMinhaSessao(null);
418	      setMinhaCorridaAtiva(null);
419	      setIsDriverMode(false);
420	
421	      toast({
422	        title: 'Modo Motorista Desativado',
423	        description: 'Você saiu do modo motorista.',
424	      });
425	    } catch (error) {
426	      handleError(error, { domain: 'logistica', operation: 'sairModoMotorista', showToast: false });
427	      setError(
428	        error instanceof Error
429	          ? error.message
430	          : 'Erro ao sair do modo motorista',
431	      );
432	    }
433	    // eslint-disable-next-line react-hooks/exhaustive-deps
434	  }, [minhaSessao, minhaCorridaAtiva]);
435	
436	  // Atualizar localização
437	  const atualizarLocalizacao = useCallback(
438	    async (lat: number, lng: number, velocidade: number = 0) => {
439	      try {
440	        if (!minhaSessao || !minhaCorridaAtiva) return;
441	
442	        // Atualizar localização na sessão
443	        await supabase
444	          .from('sessoes_motorista')
445	          .update({
446	            latitude: lat,
447	            longitude: lng,
448	            ultima_atualizacao: new Date().toISOString(),
449	          })
450	          .eq('id', minhaSessao.id);
451	
452	        // Inserir localização na corrida
453	        await supabase.from('localizacoes_corrida').insert({
454	          corrida_id: minhaCorridaAtiva.id,
455	          latitude: lat,
456	          longitude: lng,
457	          velocidade: velocidade,
458	        });
459	
460	        // Calcular distância percorrida
461	        const ultimaLocalizacao = localizacoesCorrida
462	          .filter((l) => l.corrida_id === minhaCorridaAtiva.id)
463	          .sort(
464	            (a, b) =>
465	              new Date(b.timestamp_localizacao).getTime() -
466	              new Date(a.timestamp_localizacao).getTime(),
467	          )[0];
468	
469	        if (ultimaLocalizacao) {
470	          const distancia = calcularDistanciaMetros(
471	            ultimaLocalizacao.latitude,
472	            ultimaLocalizacao.longitude,
473	            lat,
474	            lng,
475	          );
476	
477	          // Atualizar distância percorrida
478	          await supabase
479	            .from('corridas_ativas')
480	            .update({
481	              distancia_percorrida:
482	                minhaCorridaAtiva.distancia_percorrida + distancia / 1000, // em km
483	            })
484	            .eq('id', minhaCorridaAtiva.id);
485	        }
486	      } catch (error) {
487	        handleError(error, { domain: 'logistica', operation: 'atualizarLocalizacao', showToast: false });
488	      }
489	    },
490	    [minhaSessao, minhaCorridaAtiva, localizacoesCorrida],
491	  );
492	
493	  // Função para iniciar o rastreamento automático de localização
494	  const iniciarRastreamentoLocalizacao = useCallback(() => {
495	    if (locationUpdateIntervalRef.current) return;
496	
497	    // Atualizar localização a cada 10 segundos
498	    locationUpdateIntervalRef.current = setInterval(() => {
499	      if (minhaCorridaAtiva) {
500	        navigator.geolocation.getCurrentPosition(
501	          (position) => {
502	            atualizarLocalizacao(
503	              position.coords.latitude,
504	              position.coords.longitude,
505	              position.coords.speed || 0,
506	            );
507	
508	            // Atualizar posição no cronômetro para cálculo de distância
509	            tripTimer.updatePosition({
510	              lat: position.coords.latitude,
511	              lng: position.coords.longitude,
512	            });
513	          },
514	          (error) => {
515	            handleError(error, { domain: 'logistica', operation: 'obterLocalizacaoGPS', showToast: false });
516	          },
517	          {
518	            enableHighAccuracy: true,
519	            timeout: 10000,
520	            maximumAge: 60000,
521	          },
522	        );
523	      }
524	    }, 10000);
525	  }, [minhaCorridaAtiva, atualizarLocalizacao, tripTimer]);
526	
527	  // Função para parar o rastreamento automático de localização
528	  const pararRastreamentoLocalizacao = useCallback(() => {
529	    if (locationUpdateIntervalRef.current) {
530	      clearInterval(locationUpdateIntervalRef.current);
531	      locationUpdateIntervalRef.current = null;
532	    }
533	  }, []);
534	
535	  // Iniciar corrida
536	  const iniciarCorrida = useCallback(
537	    async (destinoNome: string, destinoLat: number, destinoLng: number) => {
538	      try {
539	        if (!minhaSessao) {
540	          throw new Error(
541	            'Você precisa estar no modo motorista para iniciar uma corrida',
542	          );
543	        }
544	
545	        // Verificar se já existe uma corrida ativa no banco de dados
546	        const { data: corridaExistente, error: corridaError } = await supabase
547	          .from('corridas_ativas')
548	          .select('*')
549	          .eq('sessao_motorista_id', minhaSessao.id)
550	          .eq('status', 'ativa')
551	          .maybeSingle();
552	
553	        if (corridaError) {
554	          handleError(corridaError, { domain: 'logistica', operation: 'verificarCorridaAtiva', showToast: false });
555	          throw new Error('Erro ao verificar corridas ativas');
556	        }
557	
558	        if (corridaExistente || minhaCorridaAtiva) {
559	          toast({
560	            title: 'Corrida Ativa Encontrada',
561	            description:
562	              'Você já está em uma corrida. Finalize a corrida atual para começar outra.',
563	            variant: 'destructive',
564	          });
565	          throw new Error(
566	            'Você já está em uma corrida. Finalize a corrida atual para começar outra.',
567	          );
568	        }
569	
570	        // Obter localização atual
571	        const position = await new Promise<GeolocationPosition>(
572	          (resolve, reject) => {
573	            navigator.geolocation.getCurrentPosition(resolve, reject, {
574	              enableHighAccuracy: true,
575	              timeout: 10000,
576	              maximumAge: 60000,
577	            });
578	          },
579	        );
580	
581	        const { latitude: inicioLat, longitude: inicioLng } = position.coords;
582	
583	        // Criar nova corrida
584	        const { data: novaCorrida, error } = await supabase
585	          .from('corridas_ativas')
586	          .insert({
587	            sessao_motorista_id: minhaSessao.id,
588	            destino_nome: destinoNome,
589	            destino_latitude: destinoLat,
590	            destino_longitude: destinoLng,
591	            inicio_latitude: inicioLat,
592	            inicio_longitude: inicioLng,
593	          })
594	          .select()
595	          .single();
596	
597	        if (error) throw error;
598	
599	        setMinhaCorridaAtiva(novaCorrida);
600	
601	        // Iniciar cronômetro
602	        tripTimer.startTimer({
603	          lat: inicioLat,
604	          lng: inicioLng,
605	        });
606	
607	        // Inserir localização inicial
608	        await atualizarLocalizacao(
609	          inicioLat,
610	          inicioLng,
611	          position.coords.speed || 0,
612	        );
613	
614	        // Iniciar rastreamento automático de localização
615	        iniciarRastreamentoLocalizacao();
616	
617	        toast({
618	          title: 'Corrida Iniciada',
619	          description: `Corrida para ${destinoNome} iniciada com sucesso!`,
620	        });
621	      } catch (error) {
622	        handleError(error, { domain: 'logistica', operation: 'iniciarCorrida', showToast: false });
623	        setError(
624	          error instanceof Error ? error.message : 'Erro ao iniciar corrida',
625	        );
626	      }
627	      // eslint-disable-next-line react-hooks/exhaustive-deps
628	    },
629	    [
630	      minhaSessao,
631	      minhaCorridaAtiva,
632	      atualizarLocalizacao,
633	      iniciarRastreamentoLocalizacao,
634	    ],
635	  );
636	
637	  // Finalizar corrida
638	  const finalizarCorrida = useCallback(async () => {
639	    try {
640	      if (!minhaCorridaAtiva) {
641	        throw new Error('Não há corrida ativa para finalizar');
642	      }
643	
644	      // Parar cronômetro
645	      tripTimer.stopTimer();
646	
647	      // Parar rastreamento automático
648	      pararRastreamentoLocalizacao();
649	
650	      // Registrar localização final
651	      try {
652	        const position = await new Promise<GeolocationPosition>(
653	          (resolve, reject) => {
654	            navigator.geolocation.getCurrentPosition(resolve, reject, {
655	              enableHighAccuracy: true,
656	              timeout: 5000,
657	              maximumAge: 30000,
658	            });
659	          },
660	        );
661	        await atualizarLocalizacao(
662	          position.coords.latitude,
663	          position.coords.longitude,
664	          position.coords.speed || 0,
665	        );
666	      } catch (locationError) {
667	        wideWarn('logistica.gps.localizacaoFinalIndisponivel', 'Não foi possível obter localização final', { domain: 'logistica', attributes: { error: String(locationError) } });
668	      }
669	
670	      // Atualizar status da corrida com dados finais
671	      const { error } = await supabase
672	        .from('corridas_ativas')
673	        .update({
674	          status: 'finalizada',
675	          tempo_fim: new Date().toISOString(),
676	          distancia_percorrida: tripTimer.distance,
677	          tempo_total: tripTimer.elapsedTime,
678	        })
679	        .eq('id', minhaCorridaAtiva.id);
680	
681	      if (error) throw error;
682	
683	      setMinhaCorridaAtiva(null);
684	
685	      // Mostrar resumo da corrida
686	      toast({
687	        title: 'Corrida Finalizada',
688	        description: `Tempo: ${tripTimer.formattedTime}, Distância: ${tripTimer.formattedDistance}`,
689	      });
690	
691	      // Resetar cronômetro
692	      tripTimer.resetTimer();
693	    } catch (error) {
694	      handleError(error, { domain: 'logistica', operation: 'finalizarCorrida', showToast: false });
695	      setError(
696	        error instanceof Error ? error.message : 'Erro ao finalizar corrida',
697	      );
698	    }
699	  }, [
700	    minhaCorridaAtiva,
701	    pararRastreamentoLocalizacao,
702	    atualizarLocalizacao,
703	    tripTimer,
704	  ]);
705	
706	  // Refetch manual
707	  const refetch = useCallback(async () => {
708	    await carregarDados();
709	  }, [carregarDados]);
710	
711	  // Efeitos
712	  // Carregar dados iniciais apenas uma vez
713	  useEffect(() => {
714	    carregarDados();
715	    // eslint-disable-next-line react-hooks/exhaustive-deps
716	  }, []);
717	
718	  // Configurar realtime apenas uma vez
719	  useEffect(() => {
720	    configurarRealtime();
721	
722	    return () => {
723	      channelsRef.current.forEach((channel) => {
724	        supabase.removeChannel(channel);
725	      });
726	    };
727	  }, [configurarRealtime]);
728	
729	  // Cleanup do rastreamento de localização
730	  useEffect(() => {
731	    return () => {
732	      pararRastreamentoLocalizacao();
733	    };
734	  }, [pararRastreamentoLocalizacao]);
735	
736	  // Função para recarregar apenas as lojas
737	  const reloadLojas = useCallback(async () => {
738	    try {
739	      const { data: lojasData, error: lojasError } = await supabase
740	        .from('lojas')
741	        .select('*')
742	        .eq('ativo', true);
743	
744	      if (lojasError) throw lojasError;
745	      setLojas(lojasData || []);
746	    } catch (error) {
747	      handleError(error, { domain: 'logistica', operation: 'reloadLojas', showToast: false });
748	    }
749	  }, []);
750	
751	  return {
752	    sessoesMotorista,
753	    corridasAtivas,
754	    localizacoesCorrida,
755	    lojas,
756	    minhaSessao,
757	    minhaCorridaAtiva,
758	    loading,
759	    error,
760	    isDriverMode,
761	    entrarComoMotorista,
762	    sairModoMotorista,
763	    iniciarCorrida,
764	    finalizarCorrida,
765	    atualizarLocalizacao,
766	    refetch,
767	    reloadLojas,
768	  };
769	};
