1	/**
2	 * @module useTripTimer
3	 *
4	 * Cronômetro de viagem que rastreia tempo decorrido, distância
5	 * percorrida e velocidade média a partir de posições GPS.
6	 */
7	
8	import { useState, useEffect, useRef, useCallback } from 'react';
9	
10	/** Estado interno do cronômetro de viagem. */
11	interface TripTimerState {
12	  isRunning: boolean;
13	  elapsedTime: number; // em segundos
14	  distance: number; // em metros
15	  averageSpeed: number; // em km/h
16	  lastPosition: { lat: number; lng: number } | null;
17	}
18	
19	/** Coordenada GPS com timestamp opcional. */
20	interface Position {
21	  lat: number;
22	  lng: number;
23	  timestamp?: number;
24	}
25	
26	/**
27	 * Cronômetro de viagem com cálculo de distância via Haversine.
28	 *
29	 * Expõe métodos para iniciar, parar e resetar o timer, além de
30	 * `updatePosition` para acumular distância entre pontos GPS.
31	 * Retorna valores formatados de tempo, distância e velocidade.
32	 *
33	 * @returns Estado do timer e funções de controle/formatação.
34	 */
35	export const useTripTimer = () => {
36	  const [state, setState] = useState<TripTimerState>({
37	    isRunning: false,
38	    elapsedTime: 0,
39	    distance: 0,
40	    averageSpeed: 0,
41	    lastPosition: null,
42	  });
43	
44	  const intervalRef = useRef<NodeJS.Timeout | null>(null);
45	  const startTimeRef = useRef<number | null>(null);
46	
47	  // Função para calcular distância entre dois pontos usando Haversine
48	  const calculateDistance = useCallback(
49	    (pos1: Position, pos2: Position): number => {
50	      const R = 6371000; // Raio da Terra em metros
51	      const dLat = ((pos2.lat - pos1.lat) * Math.PI) / 180;
52	      const dLon = ((pos2.lng - pos1.lng) * Math.PI) / 180;
53	      const a =
54	        Math.sin(dLat / 2) * Math.sin(dLat / 2) +
55	        Math.cos((pos1.lat * Math.PI) / 180) *
56	          Math.cos((pos2.lat * Math.PI) / 180) *
57	          Math.sin(dLon / 2) *
58	          Math.sin(dLon / 2);
59	      const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
60	      return R * c;
61	    },
62	    [],
63	  );
64	
65	  // Iniciar cronômetro
66	  const startTimer = useCallback(
67	    (initialPosition?: Position) => {
68	      if (state.isRunning) return;
69	
70	      startTimeRef.current = Date.now();
71	
72	      setState((prev) => ({
73	        ...prev,
74	        isRunning: true,
75	        lastPosition: initialPosition || prev.lastPosition,
76	      }));
77	
78	      intervalRef.current = setInterval(() => {
79	        if (startTimeRef.current) {
80	          const elapsed = Math.floor(
81	            (Date.now() - startTimeRef.current) / 1000,
82	          );
83	          setState((prev) => ({
84	            ...prev,
85	            elapsedTime: elapsed,
86	            averageSpeed:
87	              prev.distance > 0 && elapsed > 0
88	                ? prev.distance / 1000 / (elapsed / 3600) // km/h
89	                : 0,
90	          }));
91	        }
92	      }, 1000);
93	    },
94	    [state.isRunning],
95	  );
96	
97	  // Parar cronômetro
98	  const stopTimer = useCallback(() => {
99	    if (intervalRef.current) {
100	      clearInterval(intervalRef.current);
101	      intervalRef.current = null;
102	    }
103	
104	    setState((prev) => ({
105	      ...prev,
106	      isRunning: false,
107	    }));
108	
109	    startTimeRef.current = null;
110	  }, []);
111	
112	  // Resetar cronômetro
113	  const resetTimer = useCallback(() => {
114	    stopTimer();
115	    setState({
116	      isRunning: false,
117	      elapsedTime: 0,
118	      distance: 0,
119	      averageSpeed: 0,
120	      lastPosition: null,
121	    });
122	  }, [stopTimer]);
123	
124	  // Atualizar posição e calcular distância
125	  const updatePosition = useCallback(
126	    (newPosition: Position) => {
127	      setState((prev) => {
128	        if (!prev.lastPosition) {
129	          return {
130	            ...prev,
131	            lastPosition: newPosition,
132	          };
133	        }
134	
135	        const distanceIncrement = calculateDistance(
136	          prev.lastPosition,
137	          newPosition,
138	        );
139	        const newDistance = prev.distance + distanceIncrement;
140	
141	        return {
142	          ...prev,
143	          distance: newDistance,
144	          lastPosition: newPosition,
145	          averageSpeed:
146	            newDistance > 0 && prev.elapsedTime > 0
147	              ? newDistance / 1000 / (prev.elapsedTime / 3600) // km/h
148	              : 0,
149	        };
150	      });
151	    },
152	    [calculateDistance],
153	  );
154	
155	  // Formatar tempo em HH:MM:SS
156	  const formatTime = useCallback((seconds: number): string => {
157	    const hours = Math.floor(seconds / 3600);
158	    const minutes = Math.floor((seconds % 3600) / 60);
159	    const secs = seconds % 60;
160	
161	    if (hours > 0) {
162	      return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
163	    }
164	    return `${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
165	  }, []);
166	
167	  // Formatar distância
168	  const formatDistance = useCallback((meters: number): string => {
169	    if (meters < 1000) {
170	      return `${Math.round(meters)}m`;
171	    }
172	    return `${(meters / 1000).toFixed(2)}km`;
173	  }, []);
174	
175	  // Formatar velocidade
176	  const formatSpeed = useCallback((kmh: number): string => {
177	    return `${Math.round(kmh)}km/h`;
178	  }, []);
179	
180	  // Cleanup ao desmontar
181	  useEffect(() => {
182	    return () => {
183	      if (intervalRef.current) {
184	        clearInterval(intervalRef.current);
185	      }
186	    };
187	  }, []);
188	
189	  return {
190	    ...state,
191	    startTimer,
192	    stopTimer,
193	    resetTimer,
194	    updatePosition,
195	    formatTime,
196	    formatDistance,
197	    formatSpeed,
198	    formattedTime: formatTime(state.elapsedTime),
199	    formattedDistance: formatDistance(state.distance),
200	    formattedSpeed: formatSpeed(state.averageSpeed),
201	  };
202	};
203	
204	export type { TripTimerState, Position };
