91	function dateISOFromName(name: string) {
92	  const s = String(name || '');
93	  const m = s.match(/(\d{2})[/-](\d{2})[/-](\d{2,4})$/);
94	  if (!m) return null;
95	  const dd = Number(m[1]);
96	  const mm = Number(m[2]);
97	  const yy = m[3].length === 2 ? Number(`20${m[3]}`) : Number(m[3]);
98	  const d = new Date(yy || 0, (mm || 1) - 1, dd || 1);
99	  const y = d.getFullYear();
100	  const mo = String(d.getMonth() + 1).padStart(2, '0');
101	  const da = String(d.getDate()).padStart(2, '0');
102	  return `${y}-${mo}-${da}`;
103	}
104	
105	function parseISODateLocal(iso: string) {
106	  const [y, m, d] = iso.split('-').map(Number);
107	  return new Date(y || 0, (m || 1) - 1, d || 1, 12, 0, 0, 0);
108	}
