136	function startOfWeek(date = new Date()) {
137	  const d = new Date(date);
138	  const day = d.getDay();
139	  const diff = (day === 0 ? -6 : 1) - day; // segunda-feira
140	  d.setDate(d.getDate() + diff);
141	  d.setHours(0, 0, 0, 0);
142	  return d;
143	}
